using System;
using System.Linq;
using System.IO;
using System.Text;
using System.Collections;
using System.Collections.Generic;

        public enum TypeAttack
        {
            ps = 0,//port scan
            bf = 1,//brute force
            mi = 2 //malware installation
        }

        public enum StatusAttack
        {
            none = 0,
            isBlocked = 1,
            isNextStep = 2,
            isHacked = 3 
        }
class Solution
{
    static void Main(string[] args)
    {
        int n =int.Parse(Console.ReadLine());
        var dicCompany = new Dictionary<string, int>();
        var dicCompanyOrder = new Dictionary<int, string>();
        IList<string> newData = new List<string>();
        StatusAttack statusAttack = StatusAttack.none;
       for (int i = 0; i < n; i++)
        {
            string line = Console.ReadLine();
            string[] company = line.Split(":");
            string nameCompany = company[0];
            int firewallStrength = int.Parse(company[1]);
            dicCompany.Add(nameCompany, firewallStrength);
            dicCompanyOrder[i] = nameCompany;
        }
        int a =int.Parse(Console.ReadLine());
        for(int i=0;i<a;i++)
        {
            string line=Console.ReadLine();
            string[] attack = line.Split(":");
            string nameCompany = attack[0];
            string typeCyberAttack = attack[1];
            int CyberAttackStrength = int.Parse(attack[2]);
            int firewallStrength = dicCompany.Where(p => p.Key == nameCompany).Select(p => p.Value).FirstOrDefault();
            string newLine = nameCompany + ":" + typeCyberAttack + ":" + CyberAttackStrength.ToString() + ":" + firewallStrength.ToString();
            newData.Add(newLine);
        } 
        var output = newData.Select(x => x.Split(":")).Select(x => new { nameCompany = x[0], typeCyberAttack = x[1], CyberAttackStrength = int.Parse(x[2]), firewallStrength = int.Parse(x[3]) })
                .GroupBy(w => (w.nameCompany, w.typeCyberAttack, w.firewallStrength))
                .Select(g => (g.Key.nameCompany, g.Key.typeCyberAttack, TotalAttackStrength: g.Sum(w => w.CyberAttackStrength), firewallStrength: g.Key.firewallStrength))
                .OrderBy(d => dicCompanyOrder.FirstOrDefault(d1 => d1.Value == d.nameCompany).Key).ThenBy(r => (int)Enum.Parse(typeof(TypeAttack), r.typeCyberAttack));

        foreach (var att in output)
        {
            CyberAttackOp oAttack = new CyberAttackOp(att.nameCompany, att.typeCyberAttack, att.firewallStrength, att.TotalAttackStrength);
            bool isLastStepAttack = ((int)Enum.Parse(typeof(TypeAttack), att.typeCyberAttack) == (int)TypeAttack.mi) ? true : false;

            if (statusAttack == StatusAttack.none && oAttack.isAttackBlocked())
            {
                statusAttack = StatusAttack.isBlocked;
            }
            else if ((statusAttack == StatusAttack.none || (!isLastStepAttack && statusAttack == StatusAttack.isNextStep)) && oAttack.isNextStepAttack())
            {
                statusAttack = StatusAttack.isNextStep;
            }
            else if (isLastStepAttack && statusAttack == StatusAttack.isNextStep && oAttack.isAttacksucceeded())
            {
                statusAttack = StatusAttack.isHacked;
            }
            if (isLastStepAttack)
            {
                if (statusAttack == StatusAttack.isHacked)
                {
                    Console.WriteLine($"{att.nameCompany}:Hacked");
                }
                else
                {
                    Console.WriteLine($"{att.nameCompany}:Blocked");
                }
                statusAttack = StatusAttack.none;
            }
        }
    }

    public class CyberAttackOp
    {
        private string companyName;
        private int firewallStrength;
        private string nameAttack;
        private int attackStrength;

        public CyberAttackOp(string nameCompany, string attackName, int strengthFirewall, int strengthAttack)
        {
            companyName = nameCompany;
            firewallStrength = strengthFirewall;
            nameAttack = attackName;
            attackStrength = strengthAttack;
            //Console.WriteLine($"{nameCompany},{attackName},{strengthFirewall},{strengthAttack}");
        }

        public bool isAttackBlocked()
        {
            bool isBlocked = false;
            if (firewallStrength >= 7)
            {
                isBlocked = true;
            }
            else if (firewallStrength >= 5 && firewallStrength <= 6
                        && nameAttack.Equals("bf")
                        && attackStrength < 5000
                    )
            {
                isBlocked = true;
            }
            else if (firewallStrength < 5
                        && nameAttack.Equals("mi") && attackStrength < 1000
                    )
            {
                isBlocked = true;
            }

            return isBlocked;
        }


        public bool isNextStepAttack()
        {
            bool isNextStep= false;
            //Console.WriteLine($"isNextStepAttack:{companyName},{firewallStrength},{nameAttack},{attackStrength},{((int)Enum.Parse(typeof(TypeAttack), nameAttack) == (int)TypeAttack.ps) }");

            if (((firewallStrength >= 5 && firewallStrength <= 6) && (nameAttack.Equals("bf") && attackStrength >= 5000))
                    || ((firewallStrength >= 5 && firewallStrength <= 6) && (nameAttack.Equals("ps")))
                )
            {
                isNextStep = true;
            }
            else if (
                        ((firewallStrength < 5) && (nameAttack.Equals("bf") && attackStrength >= 500)) 
                        || ((firewallStrength < 5) && (nameAttack.Equals("ps")))
                    )
            {
                isNextStep = true;
            }

            return isNextStep;
        }

        public bool isAttacksucceeded()
        {
            bool isHacked = false;

            if (firewallStrength >= 5 && firewallStrength <= 6
                        && nameAttack.Equals("mi")
                        && attackStrength >= 3000
                    )
            {
                isHacked = true;
            }
            else if (firewallStrength < 5
                        && nameAttack.Equals("mi") && attackStrength >= 1000
                    )
            {
                isHacked = true;
            }

            return isHacked;
        }

    }

}
